APPROACH: I'll implement a custom set class that behaves like a mathematical set with all the required operations. I'll use a list internally to store unique elements and ensure no duplicates are added.

```python
class CustomSet:
    def __init__(self, elements=[]):
        # Use a list to store unique elements
        self.elements = []
        for element in elements:
            self.add(element)

    def isempty(self):
        """Return True if the set is empty, False otherwise."""
        return len(self.elements) == 0

    def __contains__(self, element):
        """Return True if the set contains the element, False otherwise."""
        return element in self.elements

    def issubset(self, other):
        """Return True if every element in this set is in the other set."""
        for element in self.elements:
            if element not in other:
                return False
        return True

    def isdisjoint(self, other):
        """Return True if the set has no elements in common with the other set."""
        for element in self.elements:
            if element in other:
                return False
        return True

    def __eq__(self, other):
        """Return True if both sets contain the same elements."""
        if len(self.elements) != len(other.elements):
            return False
        for element in self.elements:
            if element not in other:
                return False
        return True

    def add(self, element):
        """Add an element to the set if it's not already present."""
        if element not in self.elements:
            self.elements.append(element)

    def intersection(self, other):
        """Return a new set with elements common to both sets."""
        result_elements = []
        for element in self.elements:
            if element in other:
                result_elements.append(element)
        return CustomSet(result_elements)

    def __sub__(self, other):
        """Return a new set with elements in this set but not in the other set."""
        result_elements = []
        for element in self.elements:
            if element not in other:
                result_elements.append(element)
        return CustomSet(result_elements)

    def __add__(self, other):
        """Return a new set with elements from both sets (union)."""
        result_elements = self.elements[:]
        for element in other.elements:
            if element not in result_elements:
                result_elements.append(element)
        return CustomSet(result_elements)
```

