from itertools import permutations

def drinks_water():
    """Return the nationality of the resident who drinks water."""
    solution = solve_zebra_puzzle()
    for house in solution:
        if house['drink'] == 'water':
            return house['nationality']
    return None

def owns_zebra():
    """Return the nationality of the resident who owns the zebra."""
    solution = solve_zebra_puzzle()
    for house in solution:
        if house['pet'] == 'zebra':
            return house['nationality']
    return None

def solve_zebra_puzzle():
    """Solve the zebra puzzle and return the solution."""
    # Define possible values for each attribute
    colors = ['red', 'green', 'ivory', 'yellow', 'blue']
    nationalities = ['englishman', 'spaniard', 'ukrainian', 'norwegian', 'japanese']
    pets = ['dog', 'snail', 'fox', 'horse', 'zebra']
    drinks = ['coffee', 'tea', 'milk', 'orange juice', 'water']
    hobbies = ['painter', 'dancer', 'reader', 'football player', 'chess player']

    # Generate all possible permutations for each attribute
    color_perms = list(permutations(colors))
    nationality_perms = list(permutations(nationalities))
    pet_perms = list(permutations(pets))
    drink_perms = list(permutations(drinks))
    hobby_perms = list(permutations(hobbies))

    # Try all combinations of permutations
    for colors_perm in color_perms:
        for nationalities_perm in nationality_perms:
            for pets_perm in pet_perms:
                for drinks_perm in drink_perms:
                    for hobbies_perm in hobby_perms:
                        # Create houses with current permutation
                        houses = []
                        for i in range(5):
                            house = {
                                'color': colors_perm[i],
                                'nationality': nationalities_perm[i],
                                'pet': pets_perm[i],
                                'drink': drinks_perm[i],
                                'hobby': hobbies_perm[i]
                            }
                            houses.append(house)

                        # Check all constraints
                        if check_constraints(houses):
                            return houses

    return None

def check_constraints(houses):
    """Check if the given arrangement satisfies all constraints."""
    # Constraint 1: There are five houses (already satisfied by our setup)

    # Constraint 2: The Englishman lives in the red house
    if not (houses[0]['nationality'] == 'englishman' and houses[0]['color'] == 'red'):
        return False

    # Constraint 3: The Spaniard owns the dog
    if not (houses[1]['nationality'] == 'spaniard' and houses[1]['pet'] == 'dog'):
        return False

    # Constraint 4: The person in the green house drinks coffee
    if not (houses[2]['color'] == 'green' and houses[2]['drink'] == 'coffee'):
        return False

    # Constraint 5: The Ukrainian drinks tea
    if not (houses[3]['nationality'] == 'ukrainian' and houses[3]['drink'] == 'tea'):
        return False

    # Constraint 6: The green house is immediately to the right of the ivory house
    green_index = -1
    ivory_index = -1
    for i, house in enumerate(houses):
        if house['color'] == 'green':
            green_index = i
        if house['color'] == 'ivory':
            ivory_index = i

    if green_index != ivory_index + 1:
        return False

    # Constraint 7: The snail owner likes to go dancing
    snail_owner_index = -1
    dancer_index = -1
    for i, house in enumerate(houses):
        if house['pet'] == 'snail':
            snail_owner_index = i
        if house['hobby'] == 'dancer':
            dancer_index = i

    if snail_owner_index != dancer_index:
        return False

    # Constraint 8: The person in the yellow house is a painter
    yellow_index = -1
    painter_index = -1
    for i, house in enumerate(houses):
        if house['color'] == 'yellow':
            yellow_index = i
        if house['hobby'] == 'painter':
            painter_index = i

    if yellow_index != painter_index:
        return False

    # Constraint 9: The person in the middle house drinks milk
    if houses[2]['drink'] != 'milk':
        return False

    # Constraint 10: The Norwegian lives in the first house
    if houses[0]['nationality'] != 'norwegian':
        return False

    # Constraint 11: The person who enjoys reading lives in the house next to the person with the fox
    reader_index = -1
    fox_owner_index = -1
    for i, house in enumerate(houses):
        if house['hobby'] == 'reader':
            reader_index = i
        if house['pet'] == 'fox':
            fox_owner_index = i

    if abs(reader_index - fox_owner_index) != 1:
        return False

    # Constraint 12: The painter's house is next to the house with the horse
    painter_index = -1
    horse_owner_index = -1
    for i, house in enumerate(houses):
        if house['hobby'] == 'painter':
            painter_index = i
        if house['pet'] == 'horse':
            horse_owner_index = i

    if abs(painter_index - horse_owner_index) != 1:
        return False

    # Constraint 13: The person who plays football drinks orange juice
    football_player_index = -1
    orange_juice_drinker_index = -1
    for i, house in enumerate(houses):
        if house['hobby'] == 'football player':
            football_player_index = i
        if house['drink'] == 'orange juice':
            orange_juice_drinker_index = i

    if football_player_index != orange_juice_drinker_index:
        return False

    # Constraint 14: The Japanese person plays chess
    japanese_index = -1
    chess_player_index = -1
    for i, house in enumerate(houses):
        if house['nationality'] == 'japanese':
            japanese_index = i
        if house['hobby'] == 'chess player':
            chess_player_index = i

    if japanese_index != chess_player_index:
        return False

    # Constraint 15: The Norwegian lives next to the blue house
    norwegian_index = -1
    blue_index = -1
    for i, house in enumerate(houses):
        if house['nationality'] == 'norwegian':
            norwegian_index = i
        if house['color'] == 'blue':
            blue_index = i

    if abs(norwegian_index - blue_index) != 1:
        return False

    return True
